key":"SS-001-S011","block_type":"paragraph","content":"ለ. ተጠማቂው ከአብራከ መንፈስ ቅዱስ ዳግም መወለድ። ቲቶ 3፥5፤ ዮሐ 3፥3።","content_hash":"02864f4fc859bc","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":"ቲቶ 3፥5; ዮሐ 3፥3","locator_label":"SS-001-S011-P006"},{"key":"SS-001-S011-P007","section_key":"SS-001-S011","block_type":"paragraph","content":"ሐ. መንፈሳዊ ድኅነትና የነፍስ ፈውስ ማግኘት። ማር 16፥16።","content_hash":"073e95d36028b9","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":"ማር 16፥16","locator_label":"SS-001-S011-P007"},{"key":"SS-001-S011-P008","section_key":"SS-001-S011","block_type":"paragraph","content":"መ. ክርስቶስን መልበስ (መምሰል)። ገላ 3፥27።","content_hash":"001a119d52884e","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":"ገላ 3፥27","locator_label":"SS-001-S011-P008"},{"key":"SS-001-S011-P009","section_key":"SS-001-S011","block_type":"paragraph","content":"ሠ. ንጽሕና፣ ቅድስና፣ የዘለዓለም ሕይወት፣ የመንፈስ ቅዱስ ጸጋና ከምዕመናን ጋር አንድነት ማግኘት።","content_hash":"14b9d40a3b5dcd","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S011-P009"}]}'::jsonb),
  ('{"book":{"slug":"seven-sacraments-baptism-en","title":"Seven Sacraments — Baptism","title_amharic":"ሰባቱ ምሥጢራት — ምሥጢረ ጥምቀት","title_english":"Seven Sacraments — Baptism","title_geez":null,"language":"en","collection_key":"seven-sacraments-baptism","source_document_name":"01-baptism_1.md","source_document_sha256":"E1E25CDF45E970B27EF012EA875290C38651C0A72E35DF91A02EA9983B292BF3","author":null,"category":"Sacraments","description":"Partial Seven Sacraments collection: the Baptism chapter only.","document_type":"chapter_collection"},"sections":[{"key":"SS-001","parent_key":null,"level":1,"title":"1 The Sacrament of Baptism","source_heading":"1 The Sacrament of Baptism","page_start":null,"page_end":null},{"key":"SS-001-S001","parent_key":"SS-001","level":2,"title":"1.1 Baptism in the Old Testament","source_heading":"1.1 Baptism in the Old Testament","page_start":null,"page_end":null},{"key":"SS-001-S002","parent_key":"SS-001","level":2,"title":"1.2 Baptism in the New Testament","source_heading":"1.2 Baptism in the New Testament","page_start":null,"page_end":null},{"key":"SS-001-S003","parent_key":"SS-001","level":2,"title":"1.3 Figures and Prophecies of Baptism","source_heading":"1.3 Figures and Prophecies of Baptism","page_start":null,"page_end":null},{"key":"SS-001-S004","parent_key":"SS-001","level":2,"title":"1.4 The Institution of Baptism in the New Testament","source_heading":"1.4 The Institution of Baptism in the New Testament","page_start":null,"page_end":null},{"key":"SS-001-S005","parent_key":"SS-001","level":2,"title":"1.5 The Baptism of the Lord","source_heading":"1.5 The Baptism of the Lord","page_start":null,"page_end":null},{"key":"SS-001-S006","parent_key":"SS-001","level":2,"title":"1.6 The Baptism of People and the Preparation for It","source_heading":"1.6 The Baptism of People and the Preparation for It","page_start":null,"page_end":null},{"key":"SS-001-S007","parent_key":"SS-001","level":2,"title":"1.7 Why Baptism Is Not Repeated","source_heading":"1.7 Why Baptism Is Not Repeated","page_start":null,"page_end":null},{"key":"SS-001-S008","parent_key":"SS-001","level":2,"title":"1.8 Kinds of Baptism","source_heading":"1.8 Kinds of Baptism","page_start":null,"page_end":null},{"key":"SS-001-S009","parent_key":"SS-001","level":2,"title":"1.9 The Baptism of the Apostles and of the Souls","source_heading":"1.9 The Baptism of the Apostles and of the Souls","page_start":null,"page_end":null},{"key":"SS-001-S010","parent_key":"SS-001","level":2,"title":"1.10 The Mateb (Baptismal Cord)","source_heading":"1.10 The Mateb (Baptismal Cord)","page_start":null,"page_end":null},{"key":"SS-001-S011","parent_key":"SS-001","level":2,"title":"1.11 The Visible Service and the Invisible Grace","source_heading":"1.11 The Visible Service and the Invisible Grace","page_start":null,"page_end":null}],"passages":[{"key":"SS-001-S001-P001","section_key":"SS-001-S001","block_type":"paragraph","content":"a. Jewish baptism: in the Old Testament, baptism was washing, immersion and purification with water. When a feast was celebrated in the Old Testament, the people gathering to keep the feast had to be sprinkled with water, and all the vessels needed to prepare for the feast had to be purified with water (Lev. 6:27). There were also things believed to defile a person or an object (the holy vessels); unless these were washed with water they were not allowed to enter the camp. Since anyone who touched the corpse of a dead person, or entered the tent in which someone had died, was considered unclean, washing and purification with water was the customary law (Num. 19:18; Ps. 50:51). A person from outside the Old Covenant had to be circumcised and washed. When he accepted the faith of the Law (Orit), before he entered the community of the Jews, he was regarded on entering their faith as a newborn child. His separation from uncircumcision was believed to be like coming out of the grave.","content_hash":"0e33de2bc8eea6","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S001-P001"},{"key":"SS-001-S001-P002","section_key":"SS-001-S001","block_type":"paragraph","content":"b. The baptism of the Essenes: it is said that these people, who lived in the monastery called Qumran near the Dead Sea, had a baptism somewhat different from that of the Jews. When a follower of any faith joined their community, they received him by baptizing him. History also tells that they performed a baptism of purification for the sick. In addition, they anointed, and they baptized their first-born children.","content_hash":"1c8e97be30e17f","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S001-P002"},{"key":"SS-001-S001-P003","section_key":"SS-001-S001","block_type":"paragraph","content":"The baptism of John","content_hash":"151431f2f58b0b","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S001-P003"},{"key":"SS-001-S001-P004","section_key":"SS-001-S001","block_type":"paragraph","content":"John baptized with the baptism of repentance (Mark 1:4). John''s baptism prepared for the baptism of Christ; it made people worthy to receive Christ''s baptism and to become heirs in the Kingdom of God. John''s baptism signifies two things:","content_hash":"07871022a28476","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":"Mark 1:4","locator_label":"SS-001-S001-P004"},{"key":"SS-001-S001-P005","section_key":"SS-001-S001","block_type":"list_item","content":"1. turning from sin to forgiveness, and from the worship of idols to the worship of God;","content_hash":"055caa05966083","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S001-P005"},{"key":"SS-001-S001-P006","section_key":"SS-001-S001","block_type":"list_item","content":"2. it shows receiving the forgiveness of sins and becoming one with the community of the righteous.","content_hash":"175a559a05d21c","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S001-P006"},{"key":"SS-001-S001-P007","section_key":"SS-001-S001","block_type":"paragraph","content":"The baptism performed in the Old Testament was not a sacrament such as the one performed in the New Testament. The baptism of the Old Testament was a baptism of purification (John 2:6).","content_hash":"0662c7838cc076","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":"John 2:6","locator_label":"SS-001-S001-P007"},{"key":"SS-001-S002-P001","section_key":"SS-001-S002","block_type":"paragraph","content":"In the New Testament, Baptism is one of the sacraments of the Church that are not repeated. Its meaning is to be immersed, plunged, dipped — from the hair of the head to the nails of the feet — in water over which prayer has been said (the water of life, the water from the side [of Christ]), in the name of the Holy Trinity. This sacrament is the entrance door to all the sacraments of the Church.","content_hash":"007eb0af46a992","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S002-P001"},{"key":"SS-001-S002-P002","section_key":"SS-001-S002","block_type":"paragraph","content":"The necessity of Baptism","content_hash":"1bf42b50aa16a5","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S002-P002"},{"key":"SS-001-S002-P003","section_key":"SS-001-S002","block_type":"list_item","content":"1. We receive salvation (Mark 16:16).","content_hash":"028d9c30cf8d52","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":"Mark 16:16","locator_label":"SS-001-S002-P003"},{"key":"SS-001-S002-P004","section_key":"SS-001-S002","block_type":"list_item","content":"2. We are born again of water and the Spirit (John 3:3; Titus 3:5; Eph. 5:26).","content_hash":"1ecd0151269aeb","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":"John 3:3; Titus 3:5","locator_label":"SS-001-S002-P004"},{"key":"SS-001-S002-P005","section_key":"SS-001-S002","block_type":"list_item","content":"3. We die with our Lord in a death like His death, and we rise in a resurrection like His resurrection (Rom. 6:3; Col. 2:12).","content_hash":"1917d3d5ef0674","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S002-P005"},{"key":"SS-001-S002-P006","section_key":"SS-001-S002","block_type":"list_item","content":"4. We receive forgiveness of sins. Faith is the foundation, but it is made perfect in Baptism (Acts 22:16; 1 Cor. 6:11; Acts 2:37). \"We believe in one baptism for the forgiveness of sins.\" — the Creed.","content_hash":"059b28d0a37eda","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":"Acts 22:16; Acts 2:37","locator_label":"SS-001-S002-P006"},{"key":"SS-001-S002-P007","section_key":"SS-001-S002","block_type":"list_item","content":"5. In Baptism we receive new life; our defiled body is renewed and sanctified (Rom. 6:4).","content_hash":"1b0bb131ff4d1a","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S002-P007"},{"key":"SS-001-S002-P008","section_key":"SS-001-S002","block_type":"list_item","content":"6. Through Baptism we become members of the Church. In the age of the Law, circumcision was a religious obligation in order to belong to the people of God. In the age of the New Covenant, Baptism makes all who believe in Christ partakers of the grace found in the holy Church (Col. 2:11).","content_hash":"04c973319ebf80","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S002-P008"},{"key":"SS-001-S003-P001","section_key":"SS-001-S003","block_type":"list_item","content":"1. Israel''s crossing of the Red Sea and passing through the cloud: \"they were baptized in the cloud and in the sea,\" it says (1 Cor. 10:1–2; Ex. 14:22; Heb. 11:29).","content_hash":"0ee6f2f5c2af3b","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S003-P001"},{"key":"SS-001-S003-P002","section_key":"SS-001-S003","block_type":"list_item","content":"2. Noah''s ark, in which eight souls were kept safe, is a figure of Baptism (1 Pet. 3:20; Gen. 6:13–22).","content_hash":"0572f87fa734e9","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S003-P002"},{"key":"SS-001-S003-P003","section_key":"SS-001-S003","block_type":"list_item","content":"3. Circumcision, the sign of the covenant (Col. 2:11; Gen. 17:23).","content_hash":"0ae727cf3c1546","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S003-P003"},{"key":"SS-001-S003-P004","section_key":"SS-001-S003","block_type":"list_item","content":"4. Abraham crossing the Jordan and meeting Melchizedek (Gen. 14:20).","content_hash":"1e1c8d243f4bfd","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S003-P004"},{"key":"SS-001-S003-P005","section_key":"SS-001-S003","block_type":"list_item","content":"5. Elijah crossing the river Jordan and meeting Melchizedek (Gen. 14:20).","content_hash":"0a76885ad95741","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S003-P005"},{"key":"SS-001-S003-P006","section_key":"SS-001-S003","block_type":"list_item","content":"6. Naaman the Syrian washing in the water of the Jordan and being cleansed of his leprosy (2 Kings 5:14).","content_hash":"04b5d124e16841","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":"2 Kings 5:14","locator_label":"SS-001-S003-P006"},{"key":"SS-001-S003-P007","section_key":"SS-001-S003","block_type":"list_item","content":"7. The baptism of John the Baptist (Matt. 11:3, 11). These are figures taken in some measure for Baptism; the baptism of the Old Testament did not grant complete salvation.","content_hash":"0c444190cd0213","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S003-P007"},{"key":"SS-001-S003-P008","section_key":"SS-001-S003","block_type":"list_item","content":"8. Jewish baptism: this baptism is known as the baptism of purification. It is the baptism used when peoples outside the Jewish faith wished to join the Jews, and when they bought vessels from the Gentiles.","content_hash":"0d3aa7775bd7a8","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S003-P008"},{"key":"SS-001-S003-P009","section_key":"SS-001-S003","block_type":"paragraph","content":"Prophecies","content_hash":"1bf976f4a10fbf","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S003-P009"},{"key":"SS-001-S003-P010","section_key":"SS-001-S003","block_type":"list_item","content":"1. \"I will sprinkle clean water upon you, and you shall be clean\" (Ezek. 36:25). The clean water spoken of is the water of Baptism.","content_hash":"1f6961252788c4","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S003-P010"},{"key":"SS-001-S003-P011","section_key":"SS-001-S003","block_type":"list_item","content":"2. \"For He delights in mercy… and He will cast our sins into the depths of the sea\" (Mic. 7:19). The deep sea is a figure of Baptism.","content_hash":"194fc051a58dad","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S003-P011"},{"key":"SS-001-S003-P012","section_key":"SS-001-S003","block_type":"list_item","content":"3. From within the sea come creatures that fly with their wings, creatures that walk on their feet and creatures that creep on their bellies. So too, in Baptism, people receive one adoption and come to different ranks:","content_hash":"07caddaf49a045","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S003-P012"},{"key":"SS-001-S003-P013","section_key":"SS-001-S003","block_type":"paragraph","content":"a. Those that fly with wings — a figure of the martyrs;","content_hash":"07dda08b919f45","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S003-P013"},{"key":"SS-001-S003-P014","section_key":"SS-001-S003","block_type":"paragraph","content":"b. Those that walk on their feet — a figure of those who live enclosed in monasteries;","content_hash":"1055bb48cbf2cc","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S003-P014"},{"key":"SS-001-S003-P015","section_key":"SS-001-S003","block_type":"paragraph","content":"c. Those that creep on their bellies — a figure of Christians who live in the world according to the Law.","content_hash":"0b09a8aefe6539","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S003-P015"},{"key":"SS-001-S004-P001","section_key":"SS-001-S004","block_type":"paragraph","content":"Our Lord established Baptism by action (Matt. 3:13–16), by teaching (John 3:5) and by command (Matt. 28:19). But the full grace of the Sacrament of Baptism was given with the descent of the Holy Spirit at Pentecost (Acts 2:1–5).","content_hash":"16dd6de8121bab","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":"John 3:5; Acts 2:1–5","locator_label":"SS-001-S004-P001"},{"key":"SS-001-S005-P001","section_key":"SS-001-S005","block_type":"paragraph","content":"The Lord was baptized in His thirtieth year after His birth from our Lady, in the Year of Luke, on Tir 11, on Tuesday night at the first hour.","content_hash":"199da9048065db","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S005-P001"},{"key":"SS-001-S005-P002","section_key":"SS-001-S005","block_type":"paragraph","content":"Why the Lord was baptized","content_hash":"08011fb0122894","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S005-P002"},{"key":"SS-001-S005-P003","section_key":"SS-001-S005","block_type":"paragraph","content":"a. For humility, for teaching, and as an example (John 13:1–17).","content_hash":"002efb9d68f89d","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":"John 13:1–17","locator_label":"SS-001-S005-P003"},{"key":"SS-001-S005-P004","section_key":"SS-001-S005","block_type":"paragraph","content":"b. To blot out the bond of debt that had been cast into the Jordan (Col. 2:14).","content_hash":"13ecbf8214fc87","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S005-P004"},{"key":"SS-001-S005-P005","section_key":"SS-001-S005","block_type":"paragraph","content":"c. So that He might reveal to us the mystery of the Trinity (Matt. 3:13).","content_hash":"1e1f0061a9e815","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S005-P005"},{"key":"SS-001-S005-P006","section_key":"SS-001-S005","block_type":"paragraph","content":"d. To bless our baptism through His baptism.","content_hash":"05d294748a4b2b","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S005-P006"},{"key":"SS-001-S005-P007","section_key":"SS-001-S005","block_type":"paragraph","content":"Why He was baptized in His thirtieth year","content_hash":"0c41a215405879","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S005-P007"},{"key":"SS-001-S005-P008","section_key":"SS-001-S005","block_type":"list_item","content":"1. Just as, under the Law, one could be chosen for priestly service at thirty years of age, so He too began His work as High Priest, as Teacher and as Saviour at thirty years of age, with Baptism.","content_hash":"039e1417df406a","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S005-P008"},{"key":"SS-001-S005-P009","section_key":"SS-001-S005","block_type":"list_item","content":"2. To restore the adoption that Adam — who was created as a grown man of about thirty years and was given adoption on his fortieth day — later lost because of sin.","content_hash":"0c1e794d7e21c5","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S005-P009"},{"key":"SS-001-S005-P010","section_key":"SS-001-S005","block_type":"paragraph","content":"Why He was baptized in the Jordan","content_hash":"09d0047a076e20","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S005-P010"},{"key":"SS-001-S005-P011","section_key":"SS-001-S005","block_type":"list_item","content":"1. So that the prophecy of the prophets might be fulfilled (Ps. 113:3).","content_hash":"06cf5120316a56","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S005-P011"},{"key":"SS-001-S005-P012","section_key":"SS-001-S005","block_type":"list_item","content":"2. So that He might blot out for us the bond of debt that had been cast into the Jordan (Col. 2:14). \"He tore up the bond of debt of Adam and Eve.\" — St. Ephrem.","content_hash":"1086d62652871b","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S005-P012"},{"key":"SS-001-S005-P013","section_key":"SS-001-S005","block_type":"list_item","content":"3. So that He might make the figure a reality for us.","content_hash":"01b3aebce04f43","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S005-P013"},{"key":"SS-001-S005-P014","section_key":"SS-001-S005","block_type":"paragraph","content":"The Jordan has one source above; lower down it is divided by an island. The branch that passes on the side of Israel is called Yor, and the branch that passes on the side of the Gentiles is called Danos. Further down they meet again. The single source of the Jordan signifies that all humanity has one source. Its division by the island is a figure of the separation of Israel, by the Law, and the Gentiles, by idolatry. Their meeting further down is a figure of the people [Israel] and the Gentiles coming to believe in the one Gospel.","content_hash":"11b2ce4e2687ac","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S005-P014"},{"key":"SS-001-S005-P015","section_key":"SS-001-S005","block_type":"paragraph","content":"Alternatively: the single source of the Jordan signifies that the source of all humanity is one Adam. Its division by the island is a figure of Israel being set apart by circumcision and the Gentiles by uncircumcision. Its meeting below, and the Lord''s being baptized at the place of meeting, shows that He came to make the Gentiles and the people [Israel] one through His baptism.","content_hash":"16a5fa135c2053","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S005-P015"},{"key":"SS-001-S005-P016","section_key":"SS-001-S005","block_type":"paragraph","content":"Why He was baptized by the hand of John","content_hash":"06992223b72388","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S005-P016"},{"key":"SS-001-S005-P017","section_key":"SS-001-S005","block_type":"list_item","content":"1. Because He came into this world for humility and not for exaltation — to teach us humility.","content_hash":"006ab2179f436e","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S005-P017"},{"key":"SS-001-S005-P018","section_key":"SS-001-S005","block_type":"list_item","content":"2. Had the Lord, when He was establishing the order for us, said to John, \"Come and baptize me,\" kings, nobles and the rich would say to priests even today, \"Come and baptize us.\" It was to teach that everyone must go to the church, to the priests, to be baptized.","content_hash":"154637be347a9f","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S005-P018"},{"key":"SS-001-S005-P019","section_key":"SS-001-S005","block_type":"paragraph","content":"In whose name the Lord was baptized","content_hash":"1f6e0c142a8c5c","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S005-P019"},{"key":"SS-001-S005-P020","section_key":"SS-001-S005","block_type":"paragraph","content":"When the Lord said to John, \"Baptize me,\" John asked Him: \"Others I baptize in Your name; in whose name shall I baptize You? I cannot baptize You in the name of the Father, for the Father, Your Father, abides in You. I cannot baptize You in the name of the Son, for You are the Son. I cannot baptize You in the name of the Holy Spirit, for the Holy Spirit, Your life, abides in You. In whose name, then, shall I baptize You?\" And the Lord said to him: \"Baptize me, saying: ''You who are a priest for ever after the order of Melchizedek, who reveal the light, Son of the Father by nature, have mercy on me.''\" And he baptized Him as He had told him. He stretched out his hands over His head; he held them above it and did not lay them on Him. By this he meant: the sacrifices of the Law have passed away; from now on You are the sacrifice.","content_hash":"19dff737ba0ce0","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S005-P020"},{"key":"SS-001-S005-P021","section_key":"SS-001-S005","block_type":"paragraph","content":"Why John did not lay his hands on Him","content_hash":"17d8522237712b","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S005-P021"},{"key":"SS-001-S005-P022","section_key":"SS-001-S005","block_type":"list_item","content":"1. Lest it be said that John honoured Him through baptism and gave Him exaltation.","content_hash":"0792f1e9a46a85","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S005-P022"},{"key":"SS-001-S005-P023","section_key":"SS-001-S005","block_type":"list_item","content":"2. Because the Godhead cannot be touched by hand.","content_hash":"0f5761564b612d","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S005-P023"},{"key":"SS-001-S005-P024","section_key":"SS-001-S005","block_type":"paragraph","content":"Why He was baptized at night","content_hash":"1a1c93f806e034","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S005-P024"},{"key":"SS-001-S005-P025","section_key":"SS-001-S005","block_type":"paragraph","content":"It was to show that the light of righteousness had risen for a people that was in the darkness of sin, and that the Gospel, which is light, had been revealed to a people that lived under the Law, which is likened to darkness (Isa. 9:1). Alternatively: the Lord''s birth, His baptism, His resurrection and also His second coming are at night. The reason is that the light that follows the night is a figure of our passing from death to life, from darkness to light, from Sheol to Paradise. Alternatively: since the Holy Spirit descends in the likeness of a dove, people would have said, \"What descended on the Lord was a dove, not the Holy Spirit.\" There are no doves [flying] at night; therefore it was so that it might be known that it was the Holy Spirit.","content_hash":"17d7340ab37701","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S005-P025"},{"key":"SS-001-S005-P026","section_key":"SS-001-S005","block_type":"paragraph","content":"Why the Holy Spirit descended on the Lord after He came up out of the water","content_hash":"19628886d8e7cb","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S005-P026"},{"key":"SS-001-S005-P027","section_key":"SS-001-S005","block_type":"paragraph","content":"a. Because they honoured John, they would have said that the Holy Spirit descended upon John and not upon the Lord, since while the Lord was in the water He was not apart from John.","content_hash":"0b78a83476c382","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S005-P027"},{"key":"SS-001-S005-P028","section_key":"SS-001-S005","block_type":"paragraph","content":"b. Because they knew that there is an angel who blesses the water, so that it might not be said that [the Spirit came] to bless the water and not for the Lord.","content_hash":"0af3bcd52dfc10","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S005-P028"},{"key":"SS-001-S005-P029","section_key":"SS-001-S005","block_type":"paragraph","content":"c. Because they would have said, \"A dove that found no resting place, flying over the water, rested on Him.\" To remove that thought, the Holy Spirit descended in the likeness of a dove after He had come up out of the water.","content_hash":"0249b875d3d944","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S005-P029"},{"key":"SS-001-S005-P030","section_key":"SS-001-S005","block_type":"paragraph","content":"Why the Holy Spirit descended in the likeness of a dove","content_hash":"18812001e9b0a0","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S005-P030"},{"key":"SS-001-S005-P031","section_key":"SS-001-S005","block_type":"paragraph","content":"a. In the days of Noah, the dove came carrying an olive branch to say that the waters of the flood had abated. So too the Holy Spirit descended in the likeness of a dove to say that the sea of sin had abated.","content_hash":"1fe19a027ac4d4","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S005-P031"},{"key":"SS-001-S005-P032","section_key":"SS-001-S005","block_type":"paragraph","content":"b. A dove does not leave its place, even if it is struck or its eggs are spoiled, unless its nest is destroyed. So too the Holy Spirit does not depart from His creatures unless they commit sin and deny Him completely.","content_hash":"19b4e382c2df87","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S005-P032"},{"key":"SS-001-S005-P033","section_key":"SS-001-S005","block_type":"paragraph","content":"c. A dove is gentle and bears no grudge or vengeance; the Holy Spirit too renounces vengeance and is forgiving. Therefore He descended in the likeness of a dove.","content_hash":"0181af4625a853","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S005-P033"},{"key":"SS-001-S006-P001","section_key":"SS-001-S006","block_type":"list_item","content":"1. For a catechumen: a catechumen (nius kristiyan) is someone who did not believe in Jesus Christ and remained unbaptized, but who later came to believe and has come forward having believed and accepted the faith, dogma and canons of the holy Church. Since he must learn and believe before he is baptized, he takes part for three years in the common prayer of the Church (the Liturgy) as far as it is allowed: he stays until the middle of the Liturgy, where it says \"Tsa''u nius kristiyan\" (\"Go out, you who are catechumens\"), and then leaves, because what follows is called the fruit of the Liturgy — the Liturgy of Holy Communion is celebrated — and he does not partake of this sacrament. Such a person needs teaching, faith and canon (penance) (Mark 16:16; Acts 2:38). If this person learns quickly and completes his instruction, he may not need to stay as long as three years. A catechumen is made to stay three years in view of the fact that the Lord, after teaching the apostles for three years, washed their feet and so accomplished their baptism. When a new believer comes forward, they teach him for three years and then, having recited [the prayer] \"Egziabher ze-Birhanat\" (\"God of lights\"), they baptize him. Satan, who used to make him worship idols and commit sin, lets him go.","content_hash":"144d4fb36fe24f","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":"Mark 16:16; Acts 2:38","locator_label":"SS-001-S006-P001"},{"key":"SS-001-S006-P002","section_key":"SS-001-S006","block_type":"paragraph","content":"For children: the parents of children prepare a baptismal sponsor for the child — a godfather or a godmother. The sponsor promises to teach the child the faith. The sponsor, together with the child, performs the Creed and the other necessary prayers and rites (Mark 2:1–5). When we say that children need a parent or a baptismal sponsor, we do not mean that they do not believe. Only God knows the faith of children; we cannot examine it, because faith begins in the womb. We have seen the faith of many children while they were in the womb — for example, the Baptizer of the Godhead, St. John (Luke 1); the prophet Jeremiah (Jer. 1:5); St. David (Ps. 21). But because they cannot open their mouths and speak, we said that they need a mother or a baptismal sponsor to represent their faith. In this way we find it written in Scripture that many children received salvation through the faith of their mothers (John 4).","content_hash":"1dfa1235f29702","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":"Mark 2:1–5","locator_label":"SS-001-S006-P002"},{"key":"SS-001-S006-P003","section_key":"SS-001-S006","block_type":"list_item","content":"2. Baptism in the name of the Trinity.","content_hash":"0d0d74cac98d44","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S006-P003"},{"key":"SS-001-S006-P004","section_key":"SS-001-S006","block_type":"list_item","content":"3. Baptism with water: the Church performs Baptism with running water, flowing water, blessed water.","content_hash":"0d166248eaa6ca","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S006-P004"},{"key":"SS-001-S006-P005","section_key":"SS-001-S006","block_type":"paragraph","content":"The age of Baptism","content_hash":"1c7703a4a4ae95","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S006-P005"},{"key":"SS-001-S006-P006","section_key":"SS-001-S006","block_type":"paragraph","content":"According to the order of our Church there is no fixed age limit for Baptism. The Church teaches, prepares and baptizes everyone who believes and comes seeking adoption by God. But for children whose parents are followers of the Church, she baptizes them on the 40th and the 80th day, on the basis of the Holy Scriptures and of their family''s faith (Mark 2:1–5; Lev. 12:1–5; Book of Jubilees 4:9). If the child is in danger of death, however, he is brought to church by a guardian before that day and baptized. He comes with a guardian because his mother is not yet purified from the custom of women.","content_hash":"0de7b997e8bc75","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":"Mark 2:1–5","locator_label":"SS-001-S006-P006"},{"key":"SS-001-S006-P007","section_key":"SS-001-S006","block_type":"paragraph","content":"Reasons for baptizing children","content_hash":"1123a6703c4f27","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S006-P007"},{"key":"SS-001-S006-P008","section_key":"SS-001-S006","block_type":"list_item","content":"1. Since the first human beings, Adam and Eve, entered Paradise from the place where they were created, Elda, Adam on the 40th day and Eve on the 80th, the Church accordingly administers the Baptism through which they receive adoption and are betrothed to the Kingdom of God (Jubilees 4:9).","content_hash":"0da6107a5f202a","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S006-P008"},{"key":"SS-001-S006-P009","section_key":"SS-001-S006","block_type":"list_item","content":"2. She baptizes children on the faith of their families (Mark 2:5; Matt. 15:22–28).","content_hash":"0c938f76c79e87","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":"Mark 2:5","locator_label":"SS-001-S006-P009"},{"key":"SS-001-S006-P010","section_key":"SS-001-S006","block_type":"list_item","content":"3. Circumcision, which was performed under the Law, is a figure of Baptism. Circumcision was performed on infants; Baptism too is now performed on infants (Gen. 17:23; Col. 2:11).","content_hash":"02156cafc416ee","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S006-P010"},{"key":"SS-001-S006-P011","section_key":"SS-001-S006","block_type":"list_item","content":"4. Because the Lord gave His grace to infants as well (Jer. 1:5; Luke 1:15).","content_hash":"1ae93e27b67cfc","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":"Luke 1:15","locator_label":"SS-001-S006-P011"},{"key":"SS-001-S006-P012","section_key":"SS-001-S006","block_type":"list_item","content":"5. Since the promise of salvation was given to all (Acts 2:39), the Church baptizes on this basis.","content_hash":"00e47675460073","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":"Acts 2:39","locator_label":"SS-001-S006-P012"},{"key":"SS-001-S006-P013","section_key":"SS-001-S006","block_type":"list_item","content":"6. When Israel came out free from slavery, they crossed the Red Sea and the Jordan. This was a figure of Baptism. When they crossed the sea, the infants crossed with them; therefore the Church baptizes infants, even though they do not [yet] confess belief (1 Cor. 10:1–3).","content_hash":"1321fc45c044eb","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S006-P013"},{"key":"SS-001-S006-P014","section_key":"SS-001-S006","block_type":"list_item","content":"7. In John 3:5 He said, \"Truly, truly, I say to you, unless one [lit. a person] is born of water and the Spirit, he cannot enter the Kingdom of God.\" Since the word \"person\" includes infants as well, the Church baptizes them in their infancy.","content_hash":"169a41ee9ee925","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":"John 3:5","locator_label":"SS-001-S006-P014"},{"key":"SS-001-S006-P015","section_key":"SS-001-S006","block_type":"list_item","content":"8. Just as the apostles, when they baptized, baptized whole households, so the Church, taking the apostles as her example, baptizes [children] (1 Cor. 1:16; Acts 16:33).","content_hash":"07d8327863b47b","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":"Acts 16:33","locator_label":"SS-001-S006-P015"},{"key":"SS-001-S007-P001","section_key":"SS-001-S007","block_type":"list_item","content":"1. Baptism is a second birth from the Trinity. Just as a person is born once of his mother and father, so he is born once of God. Just as bodily birth is not repeated, spiritual birth is not repeated either.","content_hash":"062d27fe3d9006","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S007-P001"},{"key":"SS-001-S007-P002","section_key":"SS-001-S007","block_type":"list_item","content":"2. That the fathers'' Creed says \"We believe in one baptism\" shows that Baptism is one and is not repeated.","content_hash":"01f383ac9fcb30","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S007-P002"},{"key":"SS-001-S007-P003","section_key":"SS-001-S007","block_type":"list_item","content":"3. Circumcision, which was performed in the Old Testament, is performed once; Baptism too is performed once.","content_hash":"1d786203677574","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S007-P003"},{"key":"SS-001-S007-P004","section_key":"SS-001-S007","block_type":"list_item","content":"4. Baptism is a figure of Christ''s death and resurrection, and Christ''s death and resurrection happened once. Therefore we are baptized once (Rom. 6:4; Heb. 9:12).","content_hash":"1bd57cae79df0c","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S007-P004"},{"key":"SS-001-S007-P005","section_key":"SS-001-S007","block_type":"list_item","content":"5. Just as Jesus Christ, the founder of Baptism, was baptized once, we are baptized once (Matt. 3:16).","content_hash":"13b4a4041a3528","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S007-P005"},{"key":"SS-001-S008-P001","section_key":"SS-001-S008","block_type":"list_item","content":"1. Baptism by blood: those who believed in Christ but remained unbaptized, and later, through some circumstance or a time of trouble for the Church, receive martyrdom while bearing witness to Christ — their blood becomes their baptism and saves them (Matt. 10:32–39; Matt. 20:22; Luke 12:50).","content_hash":"062af1827c39d6","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":"Luke 12:50","locator_label":"SS-001-S008-P001"},{"key":"SS-001-S008-P002","section_key":"SS-001-S008","block_type":"list_item","content":"2. Baptism by tears: if those who have believed in Christ and accepted the faith of the Church, grieving over their sins, shedding tears and begging for forgiveness, die without receiving baptism by water because of some trouble arising against the Church, their tears are counted to them as baptism. They inherit the Kingdom of Heaven, which those who were baptized with water and the Spirit and received adoption inherit. But a person who has remained weeping and grieving for want of a priest, if God hears his prayer and he finds a priest to baptize him, cannot say, \"I have wept, I have grieved, my tears have become my baptism, so I will not be baptized.\"","content_hash":"1815e49e2a66aa","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S008-P002"},{"key":"SS-001-S008-P003","section_key":"SS-001-S008","block_type":"list_item","content":"3. Baptism by water and the Spirit: this is the true Baptism performed in the Church (John 3:5).","content_hash":"1f283aaa87f13a","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":"John 3:5","locator_label":"SS-001-S008-P003"},{"key":"SS-001-S009-P001","section_key":"SS-001-S009","block_type":"paragraph","content":"The baptism of the apostles: on the evening of Holy Thursday, in the house of Lazarus, the Lord taught the apostles baptism and humility. If it is asked how it is known that they received adoption on the evening of Holy Thursday: Baptism, adoption and the Body and Blood were obtained on one day, and they are also given on one day; therefore it is known that it was on the evening of Holy Thursday.","content_hash":"0501d508e6917d","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S009-P001"},{"key":"SS-001-S009-P002","section_key":"SS-001-S009","block_type":"paragraph","content":"The baptism of the souls: on Friday evening, while the Lord was on the Cross in His body, He was in Sheol in His soul, and there He gave His right hand to the souls who were there; that became their baptism (1 Pet. 1:11; 3:19).","content_hash":"19daf15fbb4ce9","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S009-P002"},{"key":"SS-001-S009-P003","section_key":"SS-001-S009","block_type":"paragraph","content":"How can it be said that they received adoption without being baptized in water? Formerly Adam, without being baptized in water, was baptized with the Holy Spirit and entered Paradise. Just as one cannot ask how Adam received adoption without being baptized in water, so too the souls were baptized.","content_hash":"127d34c45d4934","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S009-P003"},{"key":"SS-001-S010-P001","section_key":"SS-001-S010","block_type":"paragraph","content":"Tying the mateb has its origin in the Holy Scriptures. Tying the mateb is a figure of Christ being bound with a rope and harassed or dragged. As is shown in Haymanote Abew and in the Homily of Jacob, the tying of the mateb began in about the beginning of the sixth century after the birth of Christ, through Jacob Baradaeus (Ya''eqob ze-Elbarada''i). Bible verses that speak about the mateb: 1 Pet. 2:21; Ps. 59:1–5; Prov. 6:21; Tihz 94; Song 8:6; John 5:8; Matt. 10:32.","content_hash":"00dc8be01fd3c7","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":"John 5:8","locator_label":"SS-001-S010-P001"},{"key":"SS-001-S010-P002","section_key":"SS-001-S010","block_type":"paragraph","content":"The mateb had three colours: red, black and yellow. After baptizing people, Jacob would twist these together into one cord and tie it on them. Being of three kinds and twisted into one is a figure of the Threeness and Oneness of the Trinity. This mateb bears witness that the baptized person has received Baptism, has received adoption from the Trinity, and is a Christian.","content_hash":"15f1af23b30646","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S010-P002"},{"key":"SS-001-S011-P001","section_key":"SS-001-S011","block_type":"paragraph","content":"a. The rite of prayer that the priest performs over the water in the font deep enough to immerse the body is heard, and his blessing is seen.","content_hash":"10e495d69c8522","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S011-P001"},{"key":"SS-001-S011-P002","section_key":"SS-001-S011","block_type":"paragraph","content":"b. The person being baptized goes down into the water and comes up three times in the name of the Trinity.","content_hash":"1515f76e21ea4f","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S011-P002"},{"key":"SS-001-S011-P003","section_key":"SS-001-S011","block_type":"paragraph","content":"c. The white garment that he puts on, a figure of the general resurrection (of light).","content_hash":"0b018c9f361fcf","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S011-P003"},{"key":"SS-001-S011-P004","section_key":"SS-001-S011","block_type":"paragraph","content":"The invisible grace received in Baptism","content_hash":"05616062151de5","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S011-P004"},{"key":"SS-001-S011-P005","section_key":"SS-001-S011","block_type":"paragraph","content":"a. The font becomes the womb of the Jordan, and the water the water from [Christ''s] side.","content_hash":"0675a05e02ff73","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S011-P005"},{"key":"SS-001-S011-P006","section_key":"SS-001-S011","block_type":"paragraph","content":"b. The baptized person is born again from the womb of the Holy Spirit (Titus 3:5; John 3:3).","content_hash":"0ab838fe9ab061","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":"Titus 3:5; John 3:3","locator_label":"SS-001-S011-P006"},{"key":"SS-001-S011-P007","section_key":"SS-001-S011","block_type":"paragraph","content":"c. Receiving spiritual salvation and the healing of the soul (Mark 16:16).","content_hash":"17fdf1fc1d42f6","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":"Mark 16:16","locator_label":"SS-001-S011-P007"},{"key":"SS-001-S011-P008","section_key":"SS-001-S011","block_type":"paragraph","content":"d. Putting on (becoming like) Christ (Gal. 3:27).","content_hash":"146acfd81c8a76","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S011-P008"},{"key":"SS-001-S011-P009","section_key":"SS-001-S011","block_type":"paragraph","content":"e. Receiving purity, holiness, eternal life, the grace of the Holy Spirit and unity with the faithful.","content_hash":"0c6bb73b005713","page_start":null,"page_end":null,"review_notes":[],"chapter_reference":null,"locator_label":"SS-001-S011-P009"}]}'::jsonb);

-- Strict duplicate preflight. Existing records are never overwritten.
do $duplicates$
declare
  p jsonb;
  conflict_count integer;
begin
  for p in select payload from church_library_import_payloads loop
    select count(*) into conflict_count
      from public.church_library_books b
     where b.slug = p #>> '{book,slug}'
        or (b.collection_key = p #>> '{book,collection_key}' and b.language = p #>> '{book,language}')
        or (b.source_document_sha256 = p #>> '{book,source_document_sha256}' and b.language = p #>> '{book,language}');
    if conflict_count <> 0 then
      raise exception 'Duplicate Church Library identity for % (% matching rows)', p #>> '{book,slug}', conflict_count
        using errcode = '23505';
    end if;
  end loop;
end
$duplicates$;

create temporary table church_library_import_results(result jsonb) on commit drop;
do $import$
declare
  p jsonb;
begin
  for p in select payload from church_library_import_payloads loop
    insert into church_library_import_results(result)
    values (public.church_library_import_structured(p));
  end loop;
end
$import$;

-- Any mismatch aborts all four editions.
do $verify$
declare
  expected_books integer := (select count(*) from church_library_import_payloads);
  actual_books integer := (select count(*) from church_library_import_results);
  expected_sections integer := (select sum(jsonb_array_length(payload -> 'sections')) from church_library_import_payloads);
  actual_sections integer := (select sum((result ->> 'sections')::integer) from church_library_import_results);
  expected_passages integer := (select sum(jsonb_array_length(payload -> 'passages')) from church_library_import_payloads);
  actual_passages integer := (select sum((result ->> 'passages')::integer) from church_library_import_results);
begin
  if (expected_books, expected_sections, expected_passages) is distinct from
     (actual_books, actual_sections, actual_passages) then
    raise exception 'Import count mismatch: expected books/sections/passages %/%/%, got %/%/%',
      expected_books, expected_sections, expected_passages, actual_books, actual_sections, actual_passages;
  end if;
  if exists (
    select 1 from church_library_import_results r
    join public.church_library_books b on b.id = (r.result ->> 'book_id')::uuid
    where b.publication_status <> 'draft'
       or b.access_level <> 'private'
       or b.approved_for_ingestion
       or b.allow_search_quotes
       or b.public_retrieval_enabled
  ) then
    raise exception 'Draft/private publication gate verification failed';
  end if;
end
$verify$;

select result from church_library_import_results order by result ->> 'slug';
commit;
notify pgrst, 'reload schema';
